def tokenize(text: str) -> list[str]:
    """Tokenizes string by space, preserving quoted substrings and correctly handling escaped double quotes."""
    tokens = []
    current = []
    in_quotes = False
    i = 0
    while i < len(text):
        char = text[i]
        if char == '\\':
            # Include escaped character literally and skip it
            if i + 1 < len(text):
                current.append(text[i+1])
                i += 1  # skip next character
        elif char == '\"':
            in_quotes = not in_quotes
        elif char == ' ' and not in_quotes:
            if current:
                tokens.append(''.join(current))
                current = []
        else:
            current.append(char)
        i += 1
    if current:
        tokens.append(''.join(current))
    return tokens

